package br.com.weg.workshop.auth.repository; import br.com.weg.workshop.auth.domain.RefreshToken; import java.time.Instant; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Modifying; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; public interface RefreshTokenRepository extends JpaRepository<RefreshToken,UUID>{@org.springframework.data.jpa.repository.Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) Optional<RefreshToken> findByTokenHash(String tokenHash); @Modifying @Query("update RefreshToken t set t.revokedAt = :now where t.user.id = :userId and t.revokedAt is null") int revokeAllForUser(@Param("userId") UUID userId,@Param("now") Instant now);}
